def audit(n: int, k: int, d: int) -> dict[str, int | bool]:
    if min(n, k) < 0 or d < 1 or k > n or n < 2*d:
        raise ValueError("Require n >= 2d, d >= 1, and 0 <= k <= n")
    defect = n - 2*d
    return {"defect": defect, "ceiling": defect + 2,
            "valid": 2*d + k <= n + 2,
            "saturated": 2*d + k == n + 2}

for triple in [(100, 2, 50), (120, 22, 50), (120, 10, 50)]:
    print(triple, audit(*triple))

from __future__ import annotations

def fixed_defect_family(defect: int, distances: list[int]) -> list[tuple[int, int, int, float]]:
    if defect < 0 or any(d < 1 for d in distances):
        raise ValueError("Natural parameters required")
    k = defect + 2
    return [(2*d + defect, k, d, k/(2*d + defect)) for d in distances]

for n, k, d, rate in fixed_defect_family(10, [10, 50, 100, 500, 1000]):
    print(f"[[{n},{k},{d}]]  rate={rate:.6f}")

from __future__ import annotations

def direction_table(n: int, d: int) -> list[tuple[int, bool, bool]]:
    if n != 2*d or d < 1:
        raise ValueError("This diagnostic requires n = 2d and d >= 1")
    return [(k, 2*(d-1) <= n-k, n-k <= 2*(d-1)) for k in range(5)]

for k, genuine, reversed_relation in direction_table(100, 50):
    print(k, genuine, reversed_relation, "both" if genuine and reversed_relation else "")

