from math import floor

def certify(triples: list[tuple[int,int,int]], D: int, epsilon: float) -> tuple[int,list[float]]:
    if D < 0 or epsilon <= 0: raise ValueError("Require D>=0 and epsilon>0")
    rates: list[float] = []
    for n,k,d in triples:
        delta = n-2*d
        if delta < 0 or delta > D or 2*d+k > n+2: raise ValueError("Family fails audit")
        rates.append(k/n)
    N = floor((D+2)/epsilon)+1
    assert all(rate < epsilon for (n,_,_),rate in zip(triples,rates) if n >= N)
